-- Rollback-only tests. Apply the migration first, or prepend its body in the same transaction.
create temporary table onboarding_checks(name text,passed boolean);
create or replace function pg_temp.check_onboarding(ok boolean,label text) returns void language plpgsql as $$ begin insert into onboarding_checks values(label,coalesce(ok,false)); if not coalesce(ok,false) then raise exception 'FAILED: %',label; end if; end $$;
create or replace function pg_temp.reject_qa_content() returns trigger language plpgsql as $$
begin
 if exists(select 1 from public.projects where id=new.project_id and slug like 'atomic-failure-qa-%') then raise exception 'Synthetic content write failure'; end if;
 return new;
end $$;
create trigger qa_onboarding_content_failure before insert on public.website_content for each row execute function pg_temp.reject_qa_content();
do $$
declare a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); t1 uuid:=gen_random_uuid(); t2 uuid:=gen_random_uuid(); t3 uuid:=gen_random_uuid();
 payload jsonb; r jsonb; job uuid; project uuid; secondjob uuid; denied boolean; n integer;
begin
 insert into auth.users(id,aud,role,email) values(a,'authenticated','authenticated','onboarding-a-'||a||'@example.invalid'),(b,'authenticated','authenticated','onboarding-b-'||b||'@example.invalid');
 payload:=jsonb_build_object('provider','stripe','external_order_id','cs_qa_'||a,'external_event_id','evt_qa_'||a,'customer_email','onboarding-a-'||a||'@example.invalid','package_type','signature','couple_display_name','Synthetic a Synthetic','design_family','botanique','slug','onboarding-qa-'||a,'test_mode',false);
 r:=public.claim_paid_onboarding(payload||jsonb_build_object('external_order_id','cs_atomic_qa_'||a,'external_event_id','evt_atomic_qa_'||a,'slug','atomic-failure-qa-'||a),t1);
 secondjob:=(r->'job'->>'id')::uuid;
 denied:=false;begin perform public.prepare_paid_onboarding(secondjob,t1,a,'cipher','[]');exception when others then denied:=true;end;
 perform pg_temp.check_onboarding(denied,'content failure aborts preparation');
 perform pg_temp.check_onboarding(not exists(select 1 from public.projects where stripe_checkout_session_id='cs_atomic_qa_'||a),'content failure rolls back project insert');
 perform pg_temp.check_onboarding((select project_ready_at is null and project_id is null from public.onboarding_jobs where id=secondjob),'content failure cannot persist ready checkpoint');
 r:=public.claim_paid_onboarding(payload,t1);job:=(r->'job'->>'id')::uuid;
 perform pg_temp.check_onboarding(r->>'state'='claimed','initial order claimed');
 r:=public.claim_paid_onboarding(payload,t2);perform pg_temp.check_onboarding(r->>'state'='busy','parallel claim rejected');
 update public.onboarding_jobs set lease_until=clock_timestamp()-interval '1 second' where id=job;
 r:=public.claim_paid_onboarding(payload,t3);perform pg_temp.check_onboarding(r->>'state'='claimed','expired processing recovered');
 denied:=false;begin perform public.prepare_paid_onboarding(job,t1,a,'encrypted-fixture','[]');exception when others then denied:=true;end;
 perform pg_temp.check_onboarding(denied,'stale worker cannot create project');
 perform pg_temp.check_onboarding(not public.fail_paid_onboarding(job,t1,'stale'),'stale worker cannot overwrite new claim');
 denied:=false;begin perform public.prepare_paid_onboarding(job,null,a,'encrypted-fixture','[]');exception when others then denied:=true;end;
 perform pg_temp.check_onboarding(denied,'null claim token rejected');
 r:=public.prepare_paid_onboarding(job,t3,a,'encrypted-fixture','[]');project:=(r->>'project_id')::uuid;
 perform pg_temp.check_onboarding(r->>'project_ready_at' is not null,'project checkpoint persisted');
 perform pg_temp.check_onboarding((select project_status='active' and payment_status='paid' and owner_user_id=a from public.projects where id=project),'correct paid owner and active project');
 perform pg_temp.check_onboarding((select count(*)=1 from public.website_content where project_id=project),'content exists before delivery');
 r:=public.prepare_paid_onboarding(job,t3,a,'must-not-replace','[]');
 perform pg_temp.check_onboarding(r->>'access_payload_encrypted'='encrypted-fixture','retries preserve original email envelope');
 perform pg_temp.check_onboarding((select count(*)=1 from public.projects where stripe_checkout_session_id=payload->>'external_order_id'),'one project per paid session');
 perform pg_temp.check_onboarding((select count(*)=1 from public.website_content where project_id=project),'content retry has no duplicate');
 denied:=false;begin perform public.complete_paid_onboarding(job,t3,true);exception when others then denied:=true;end;
 perform pg_temp.check_onboarding(denied,'production cannot bypass email acceptance using test flag');
 perform public.begin_onboarding_delivery(job,t3);
 perform pg_temp.check_onboarding((select access_send_started_at is not null from public.onboarding_jobs where id=job),'delivery start persisted before provider call');
 perform public.finish_onboarding_delivery(job,t3,'synthetic-message');
 r:=public.complete_paid_onboarding(job,t3,false);
 perform pg_temp.check_onboarding(r->>'status'='completed','accepted delivery completes order');
 perform pg_temp.check_onboarding(r->>'access_payload_encrypted' is null,'completed production envelope removed');
 r:=public.claim_paid_onboarding(payload,t1);perform pg_temp.check_onboarding(r->>'state'='completed','finished order replay returns completed');
 perform public.mark_onboarding_notification(job);
 perform pg_temp.check_onboarding((select payload_snapshot->>'customer_email'=payload->>'customer_email' and payload_snapshot ? 'order_notification_sent_at' from public.onboarding_jobs where id=job),'notification preserves immutable order fields');
 denied:=false;begin perform public.claim_paid_onboarding(payload||'{"package_type":"atelier"}',t1);exception when others then denied:=true;end;
 perform pg_temp.check_onboarding(denied,'changed package on same order rejected');
 update public.projects set project_status='archived' where id=project;
 denied:=false;begin perform public.claim_paid_onboarding(payload,t1);exception when others then denied:=true;end;
 perform pg_temp.check_onboarding(denied,'replay cannot reactivate archived service');
 update public.onboarding_jobs set status='failed' where id=job;
 denied:=false;begin perform public.claim_paid_onboarding(payload,t1);exception when others then denied:=true;end;
 perform pg_temp.check_onboarding(denied,'failed order cannot resume archived service');
 update public.onboarding_jobs set status='completed' where id=job;
 update public.projects set project_status='active' where id=project;
 -- Same customer and preferred slug, different paid order: a new project, never an email-based takeover.
 payload:=payload||jsonb_build_object('external_order_id','cs_qa_second_'||a,'external_event_id','evt_qa_second_'||a,'test_mode',true);
 r:=public.claim_paid_onboarding(payload,t1);secondjob:=(r->'job'->>'id')::uuid;
 r:=public.prepare_paid_onboarding(secondjob,t1,a,'test-cipher','[]');
 perform pg_temp.check_onboarding((r->>'project_id')::uuid<>project,'second order does not attach previous customer project');
 perform pg_temp.check_onboarding(r->>'slug'=(payload->>'slug')||'-1','slug collision safely gets suffix');
 r:=public.complete_paid_onboarding(secondjob,t1,true);
 perform pg_temp.check_onboarding(r->>'status'='completed' and r->>'access_payload_encrypted'='test-cipher','explicit test may return private access without sending');
 payload:=payload||jsonb_build_object('external_order_id','cs_qa_third_'||a,'external_event_id','evt_qa_third_'||a);
 r:=public.claim_paid_onboarding(payload,t2);secondjob:=(r->'job'->>'id')::uuid;
 r:=public.prepare_paid_onboarding(secondjob,t2,b,'test-cipher','[]');
 update public.onboarding_jobs set access_send_started_at=clock_timestamp()-interval '24 hours' where id=secondjob;
 denied:=false;begin perform public.begin_onboarding_delivery(secondjob,t2);exception when others then denied:=true;end;
 perform pg_temp.check_onboarding(denied,'uncertain delivery beyond provider window requires manual review');
 perform pg_temp.check_onboarding(not has_table_privilege('anon','public.onboarding_jobs','select'),'anonymous cannot read outbox');
 perform pg_temp.check_onboarding(not has_table_privilege('authenticated','public.onboarding_jobs','select'),'customer cannot read outbox');
 perform pg_temp.check_onboarding(not has_function_privilege('anon','public.claim_paid_onboarding(jsonb,uuid)','execute'),'anonymous cannot claim order');
 perform pg_temp.check_onboarding(not has_function_privilege('authenticated','public.prepare_paid_onboarding(uuid,uuid,uuid,text,jsonb)','execute'),'customer cannot provision project');
end $$;
select json_build_object('checks',count(*),'passed',bool_and(passed),'results',json_agg(row_to_json(t))) from onboarding_checks t;
